#!/usr/bin/env python3
"""Convert a Word update document to Quarto (.qmd), cleaning up what pandoc leaves behind.

Pandoc converts the .docx faithfully, which means it preserves Word's artifacts:
per-run `[...]{dir="rtl"}` spans, figure numbers typed by hand into the caption,
and Word bookmark cross-references (`[איור 3](#_Ref237280533)`). This script turns
those into Quarto idioms:

  * `dir="rtl"` spans           -> dropped; the document sets `dir: rtl` once
  * `[איור N]` in a caption     -> a `{#fig-N}` label, number generated by Quarto
  * `[איור N](#_RefNNNN)`       -> `@fig-N`, resolved and numbered by Quarto
  * grid tables                 -> left alone (pandoc's are valid, just verbose)

Usage:
    python docx_to_qmd.py INPUT.docx -o OUTPUT.qmd [--media-dir media]
"""

from __future__ import annotations

import argparse
import re
import shutil
import subprocess
import sys
from pathlib import Path

# `[text]{dir="rtl"}` or `[text]{dir="ltr"}` -> `text`
DIR_SPAN = re.compile(r'\[([^\[\]]*)\]\{dir="(?:rtl|ltr)"\}')

# A figure whose caption carries a Word bookmark anchor and a hand-typed number:
#   ![[]{#_Ref237280533 .anchor}[איור 3]{dir="rtl"}](media/media/image5.png){width="6.1in" ...}
FIGURE = re.compile(
    r'!\[(?P<caption>.*?)\]\((?P<path>[^)]+?)\)(?:\{(?P<attrs>[^}]*)\})?'
)

# `[]{#_Ref237280533 .anchor}` — Word bookmark target, with or without a figure
ANCHOR = re.compile(r'\[\]\{#(?P<id>_Ref\d+) \.anchor\}')

# Hebrew figure label, e.g. `איור 3` / `איור 10`
FIG_LABEL = re.compile(r'איור\s+(?P<num>\d+)')

# A cross-reference link to a Word bookmark: `[איור 3](#_Ref237280533)`.
# Capture any Hebrew letter glued to the front of it — Hebrew prefixes attach
# directly to the following word ("ב" + "איור" = "באיור"), and Quarto will not
# resolve `@fig-3` when a letter precedes the `@`. A maqaf separates them.
XREF = re.compile(r'(?P<prefix>[א-ת]?)\[איור\s+(?P<num>\d+)\]\(#(?P<id>_Ref\d+)\)')

HEBREW_LETTER = re.compile(r'[א-ת]')

# `width="6.5in" height="3.37in"` -> keep width only, as a percentage-free value
WIDTH = re.compile(r'width="(?P<w>[\d.]+)in"')


def pandoc_to_markdown(docx: Path, media_dir: Path) -> str:
    """Run pandoc, extracting embedded images into media_dir."""
    if not shutil.which("pandoc"):
        sys.exit("pandoc not found on PATH (Quarto bundles one, but this script uses the standalone)")
    result = subprocess.run(
        [
            "pandoc", str(docx),
            # Force pipe tables. Pandoc defaults to grid/multiline tables, whose
            # columns are defined by exact character alignment — any editor that
            # trims whitespace silently destroys them. Pipe tables survive that
            # and are far easier to edit by hand.
            "--to=markdown-grid_tables-multiline_tables-simple_tables+pipe_tables",
            "--wrap=none",
            f"--extract-media={media_dir}",
        ],
        capture_output=True,
        text=True,
        encoding="utf-8",
    )
    if result.returncode != 0:
        sys.exit(f"pandoc failed:\n{result.stderr}")
    return result.stdout


def collect_anchor_numbers(text: str) -> dict[str, int]:
    """Map each Word bookmark id to the figure number that follows it in its caption.

    Word stores the anchor and the visible number separately, so the only way to
    know that `#_Ref237280533` means "figure 3" is to read the label next to it.
    """
    mapping: dict[str, int] = {}
    for anchor in ANCHOR.finditer(text):
        # Look at the rest of the caption/paragraph for the label Word rendered.
        tail = text[anchor.end():anchor.end() + 200]
        label = FIG_LABEL.search(tail)
        if label:
            mapping[anchor.group("id")] = int(label.group("num"))
    return mapping


def rewrite_figure(match: re.Match, anchors: dict[str, int]) -> str:
    """Turn one pandoc figure into a Quarto figure with a crossref label."""
    caption = match.group("caption")
    path = match.group("path")
    attrs = match.group("attrs") or ""

    # Which figure is this? Prefer the bookmark, fall back to a bare label.
    fig_num = None
    anchor = ANCHOR.search(caption)
    if anchor and anchor.group("id") in anchors:
        fig_num = anchors[anchor.group("id")]
    else:
        label = FIG_LABEL.search(caption)
        if label:
            fig_num = int(label.group("num"))

    # Strip the machinery out of the caption, leaving only real prose.
    caption = ANCHOR.sub("", caption)
    caption = DIR_SPAN.sub(r"\1", caption)
    # Drop the hand-typed number and any separator that trailed it — Quarto
    # generates "איור N:" itself from the crossref label.
    caption = FIG_LABEL.sub("", caption)
    caption = caption.strip().lstrip(":").strip()

    # Keep the author's width, drop pandoc's pixel-exact height so the figure
    # scales instead of being locked to a Word-specific aspect box.
    new_attrs = []
    width = WIDTH.search(attrs)
    if width:
        # Word pages are 6.5in of text; express width relative to that.
        pct = min(100, round(float(width.group("w")) / 6.5 * 100))
        new_attrs.append(f"width={pct}%")
    if fig_num is not None:
        new_attrs.insert(0, f"#fig-{fig_num}")

    attr_str = "{" + " ".join(new_attrs) + "}" if new_attrs else ""
    return f"![{caption}]({path}){attr_str}"


def rewrite_xref(match: re.Match, anchors: dict[str, int]) -> str:
    """Turn a Word bookmark link into `@fig-N`, keeping any Hebrew prefix legible."""
    num = anchors.get(match.group("id"), int(match.group("num")))
    prefix = match.group("prefix")
    # `ב@fig-3` does not resolve; `ב-@fig-3` renders as "ב-איור 3".
    separator = "-" if prefix else ""
    return f"{prefix}{separator}@fig-{num}"


def convert(text: str) -> str:
    anchors = collect_anchor_numbers(text)

    # Figures first: they contain anchors and dir spans that later passes would eat.
    text = FIGURE.sub(lambda m: rewrite_figure(m, anchors), text)

    # Cross-references become Quarto's `@fig-N`.
    text = XREF.sub(lambda m: rewrite_xref(m, anchors), text)

    # Any anchor not attached to a figure is a bookmark with nothing to point at.
    text = ANCHOR.sub("", text)

    # Now the bulk of the noise: per-run direction spans.
    # Repeat until stable, since Word nests them.
    for _ in range(5):
        new = DIR_SPAN.sub(r"\1", text)
        if new == text:
            break
        text = new

    # Pandoc escapes punctuation that needs no escaping in a .qmd, which makes
    # Hebrew prose with quotation marks painful to read and to edit.
    for escaped, plain in ((r'\"', '"'), (r"\'", "'"), (r"\>", ">"),
                           (r"\<", "<"), (r"\...", "..."), (r"\[", "["),
                           (r"\]", "]")):
        text = text.replace(escaped, plain)

    # Word's empty "line break" paragraphs become stray backslashes.
    text = re.sub(r"^\\\s*$", "", text, flags=re.MULTILINE)
    # A caption paragraph whose figure was a native Word drawing survives as a
    # bare "איור N" line with nothing attached. Drop it; the real figure has to be
    # redrawn and will carry its own caption.
    text = re.sub(r"^איור\s+\d+\s*$\n?", "", text, flags=re.MULTILINE)
    # Collapse the blank-line drifts the substitutions leave behind.
    text = re.sub(r"\n{3,}", "\n\n", text)
    # Empty headings from Word's section breaks.
    text = re.sub(r"^#+\s*$\n+", "", text, flags=re.MULTILINE)

    return text.strip() + "\n"


FIG_BLOCK = re.compile(r'^!\[.*?\]\([^)]+\)\{#fig-(?P<num>\d+)[^}]*\}$')


def reflow_figures(text: str) -> str:
    """Move each labelled figure to just after the paragraph that first cites it.

    Word floats figures, so pandoc emits them wherever the anchor happened to
    land — in this document, figures 3-8 all pile up after the paragraph that
    references figure 8. Quarto numbers figures by document order, so the numbers
    stay correct either way, but the reading order does not.
    """
    blocks = [b.strip() for b in text.split("\n\n")]

    # Where does each figure sit now, and where is it first cited?
    fig_at: dict[str, int] = {}
    first_cite: dict[str, int] = {}
    for i, block in enumerate(blocks):
        match = FIG_BLOCK.match(block)
        if match:
            fig_at.setdefault(match.group("num"), i)
        for num in re.findall(r"@fig-(\d+)", block):
            first_cite.setdefault(num, i)

    # Only figures cited *before* their current position need moving. A figure
    # that already follows its citation — or that nothing cites, like a figure
    # introduced as "the image below" — stays exactly where the author put it.
    moving = {n for n, at in fig_at.items()
              if n in first_cite and first_cite[n] < at}
    if not moving:
        return "\n\n".join(blocks)

    out: list[str] = []
    for i, block in enumerate(blocks):
        match = FIG_BLOCK.match(block)
        if match and match.group("num") in moving:
            continue  # emitted after its citation instead
        out.append(block)
        for num in re.findall(r"@fig-(\d+)", block):
            if num in moving and first_cite[num] == i:
                out.append(blocks[fig_at[num]])

    return "\n\n".join(out)


def build_frontmatter(title: str) -> str:
    """A Hebrew-first Quarto header that renders to both HTML and Word."""
    # `lang` must carry the region subtag. Pandoc writes it straight into the
    # docx as `<w:lang w:bidi="...">`, and Word only recognises full locales
    # there: with a bare `he` it silently ignores the reference document's
    # complex-script font and falls back to Times New Roman. See README.md.
    return f"""---
title: "{title}"
lang: he-IL
dir: rtl
format:
  html:
    embed-resources: true
    toc: true
    toc-title: "תוכן העניינים"
    css: rtl-fixes.css
    mainfont: David
  docx:
    # Pandoc cannot embed SVG in .docx, so Word gets the rasterized copy that
    # scripts/rasterize_svg.py writes beside each vector original.
    filters: [filters/svg-to-png.lua]
    # Word takes its fonts from this file, not from `mainfont`. Rebuild it with:
    #   python scripts/make_reference_docx.py -o templates/hebrew-reference.docx
    reference-doc: templates/hebrew-reference.docx
crossref:
  fig-title: "איור"
  tbl-title: "טבלה"
  fig-prefix: "איור"
  tbl-prefix: "טבלה"
  title-delim: ":"
---

"""


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("docx", type=Path, help="Word document to convert")
    parser.add_argument("-o", "--output", type=Path, required=True, help="output .qmd path")
    parser.add_argument("--media-dir", type=Path, default=None,
                        help="where to extract images (default: alongside the output)")
    parser.add_argument("--title", default=None, help="document title (default: from filename)")
    parser.add_argument("--no-frontmatter", action="store_true",
                        help="emit body only, for pasting into an existing .qmd")
    parser.add_argument("--reflow-figures", action="store_true",
                        help="move each figure to just after the paragraph that cites it")
    args = parser.parse_args()

    media_dir = args.media_dir or args.output.parent / "media"
    args.output.parent.mkdir(parents=True, exist_ok=True)

    raw = pandoc_to_markdown(args.docx, media_dir)
    body = convert(raw)
    if args.reflow_figures:
        body = reflow_figures(body)

    title = args.title or args.docx.stem
    # Pandoc often turns the Word title line into the first paragraph; if the
    # first line looks like a title, promote it to the frontmatter instead.
    lines = body.split("\n")
    if lines and lines[0] and not lines[0].startswith(("#", "!", "-", "|")):
        if len(lines[0]) < 80:
            title = lines[0].strip()
            body = "\n".join(lines[1:]).lstrip("\n")

    out = body if args.no_frontmatter else build_frontmatter(title) + body
    args.output.write_text(out, encoding="utf-8")

    labelled = set(re.findall(r"\{#fig-(\d+)", out))
    cited = set(re.findall(r"@fig-(\d+)", out))
    print(f"wrote {args.output}  "
          f"({len(labelled)} labelled figures, {len(cited)} cross-referenced)")

    # A reference with no figure is almost always a native Word drawing (shapes,
    # SmartArt, a drawing canvas). Those carry no image part, so nothing can be
    # extracted and the figure has to be redrawn.
    dangling = sorted(cited - labelled, key=int)
    if dangling:
        print(f"  WARNING: no image found for figure(s) {', '.join(dangling)} — "
              f"likely drawn natively in Word. Quarto will fail the reference "
              f"and renumber later figures; redraw and label them.")
    orphan = sorted(labelled - cited, key=int)
    if orphan:
        print(f"  note: figure(s) {', '.join(orphan)} are never cross-referenced.")


if __name__ == "__main__":
    main()
